  <script>
    // Pricing comparator with animated numbers
    (function(){
      const monthlyBtn = document.getElementById('monthlyBtn');
      const packageBtn = document.getElementById('packageBtn');
      let mode = 'monthly';
      const plans = Array.from(document.querySelectorAll('.plan'));

      function animateValue(el, start, end, duration){
        const startTime = performance.now();
        function step(now){
          const t = Math.min(1,(now-startTime)/duration);
          const val = Math.round(start + (end-start)*t);
          el.textContent = '$' + val;
          if(t<1) requestAnimationFrame(step);
          else el.textContent = '$' + end;
        }
        requestAnimationFrame(step);
      }

      function setMode(m){
        mode = m;
        if(m==='monthly'){ monthlyBtn.classList.add('active'); monthlyBtn.setAttribute('aria-pressed','true'); packageBtn.classList.remove('active'); packageBtn.setAttribute('aria-pressed','false'); }
        else{ packageBtn.classList.add('active'); packageBtn.setAttribute('aria-pressed','true'); monthlyBtn.classList.remove('active'); monthlyBtn.setAttribute('aria-pressed','false'); }
        plans.forEach(p=>{
          const el = p.querySelector('[data-value]');
          const from = parseInt(el.textContent.replace(/[^0-9]/g,'')) || 0;
          const to = parseInt(p.getAttribute(m==='monthly'?'data-monthly':'data-package'),10);
          animateValue(el,from,to,500);
        });
      }

      monthlyBtn.addEventListener('click',()=>setMode('monthly'));
      packageBtn.addEventListener('click',()=>setMode('package'));

      // initial load
      setTimeout(()=>setMode('monthly'),100);
    })();
  </script>
